style.css:
@-moz-document domain("myaccountcenter.com"), domain("tenantsites.webit.com"), domain("manage.webit.com") {
/* ------------------------------------------------ Code Your Own Modules ------------------------------------------------ */
ul#steBuilderWebpageModules {
    counter-reset: item;
    /* counter-reset: item itemallCount; */
}

/* Mark and number Code Your Own modules in left panel */
ul#steBuilderWebpageModules li[data-controller-name="CodeYourOwn"]:not(.ste-k-hidden) {
    border-left: 20px solid #444;
    position: relative;
}

ul#steBuilderWebpageModules li[data-controller-name="CodeYourOwn"]:not(.ste-k-hidden)::before {
    content: counter(item) " ";
    counter-increment: item;
    position: absolute;
    color: #fff;
    left: -20px;
    width: 20px;
    text-align: center;
    height: 100%;
    top: 40%;
    z-index: 20000;
}

/* Mark and number Code Your Own Sections on preview sites */
section[id*="module"]:not(.title):not(.spacer):not(.line):not(.image):not(.detailedlist):not(.summarylist):not(.textwithimage):not(.slideshow):not(.text):not(.galleryslideshow):not(.productslideshow):not(.products):not(.gallery):not(.employees):not(.forms):not(.businessinfo):not(.map):not(.inventory):not(.inventoryslideshow):not(.popularvehicles):not(.inventorysearchmodule):not(.loanappmodule):not(.inventory-search-module):not(.form):not(.loan-app-module):not(.list),
.creditQualifyBanner {
    counter-increment: item;
}

section[id*="module"]:hover:not(.title):not(.spacer):not(.line):not(.image):not(.detailedlist):not(.summarylist):not(.textwithimage):not(.slideshow):not(.text):not(.galleryslideshow):not(.productslideshow):not(.products):not(.gallery):not(.employees):not(.forms):not(.businessinfo):not(.map):not(.inventory):not(.inventoryslideshow):not(.popularvehicles):not(.inventorysearchmodule):not(.loanappmodule):not(.inventory-search-module):not(.form):not(.loan-app-module):not(.list),
.creditQualifyBanner:hover {
    position: relative;
}

section[id*="module"]:not(.title):not(.spacer):not(.line):not(.image):not(.detailedlist):not(.summarylist):not(.textwithimage):not(.slideshow):not(.text):not(.galleryslideshow):not(.productslideshow):not(.products):not(.gallery):not(.employees):not(.forms):not(.businessinfo):not(.map):not(.inventory):not(.inventoryslideshow):not(.popularvehicles):not(.inventorysearchmodule):not(.loanappmodule):not(.inventory-search-module):not(.form):not(.loan-app-module):not(.list)::before,
.creditQualifyBanner::before {
    content: counter(item) " ";
    position: absolute;
    color: #fff;
    left: 16px;
    top: 40%;
    z-index: 20000;
    opacity: 0;
    background: rgba(255, 0, 0, 0.8);
    padding: 5px 10px;
    text-shadow: 0px 0px 1px rgba(0, 0, 0, 1), 0px 0px 2px rgba(0, 0, 0, 1);
    pointer-events: none;
}

section[id*="module"]:not(.inventoryslideshow):not(.spacer):not(.businessinfo):not(.inventory-search-module):hover::before,
.creditQualifyBanner:hover::before {
    opacity: 1;
}

section[id*="module"]:not(.inventoryslideshow):not(.spacer):not(.businessinfo):not(.inventory-search-module):hover::after,
.creditQualifyBanner:hover::after {
    opacity: 1;
}

/* ------------------------------------------------ All Modules ------------------------------------------------ */

/* Mark and number other items */
ul#steBuilderWebpageModules li:not(.ste-k-hidden) {
    border-left: 20px solid rgba(0, 255, 0);
    position: relative;
}

ul#steBuilderWebpageModules li:not(.ste-k-hidden)::before {
    content: counter(item) " ";
    counter-increment: item;
    position: absolute;
    color: #111;
    left: -20px;
    width: 20px;
    text-align: center;
    height: 100%;
    top: 40%;
    z-index: 20000;
}

/* Mark all Modules in blue */
section[id*="module"]:hover,
.popular-vehicles-sections:hover {
    position: relative;
}

section[id*="module"],
.popular-vehicles-sections {
    counter-increment: item;
}

section[id*="module"]::before,
.popular-vehicles-sections::before {
    content: counter(item) " ";
    position: absolute;
    color: #111;
    left: 16px;
    top: 40%;
    z-index: 20000;
    opacity: 0;
    background: rgba(0, 255, 0, 0.8);
    padding: 5px 10px;
    pointer-events: none;
}

section[id*="module"]::after,
.popular-vehicles-sections::after {
    content: " ";
    position: absolute;
    width: 100%;
    height: 100%;
    top: 0;
    left: 0;
    box-shadow: inset 0px 0 0px 1px rgba(0, 255, 0, 0.8), inset 0px 0 20px 6px rgba(0, 255, 0, 0.5);
    z-index: 999999999;
    opacity: 0;
    pointer-events: none;
}

section[id*="module"]:hover::before,
.popular-vehicles-sections:hover::before {
    opacity: 1;
}

section[id*="module"]:hover::after,
.popular-vehicles-sections:hover::after {
    opacity: 1;
}
}
